var userConnection = Get<UserConnection>("UserConnection");
string accessToken = Get<string>("Token");
int expire = Get<int>("Expire");

var token = new Token(userConnection);
token.UpdateCacheToken(accessToken, expire);
var result = token.GetCacheToken();

Set("Result", JsonConvert.SerializeObject(result, Formatting.Indented));

return true;
